window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"jDLf_zSlV0k","speaker":"Prince 'Abdul Mateen","role":"Foreign Minister","country":"Brunei Darussalam","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=jDLf_zSlV0k","date":"20260926","title":"🇧🇳 Brunei Darussalam - Foreign Minister Addresses United Nations General Debate, 81st Session","seconds":729,"words":1396,"counts":{"claims":18,"promises":1,"attacks":0},"topics":[{"topic":"Israel-Palestine conflict","share":0.2921,"seconds":213},{"topic":"UN reform","share":0.173,"seconds":126},{"topic":"Ceremony","share":0.1136,"seconds":83},{"topic":"Brunei Darussalam reconstruction","share":0.1023,"seconds":75},{"topic":"Trust erosion","share":0.0855,"seconds":62},{"topic":"ASEAN relations","share":0.084,"seconds":61},{"topic":"Brunei Darussalam economy","share":0.0833,"seconds":61},{"topic":"International law","share":0.0661,"seconds":48}],"timeline":[[2,85,"Ceremony"],[85,148,"Trust erosion"],[149,228,"Israel-Palestine conflict"],[230,302,"Israel-Palestine conflict"],[304,366,"Israel-Palestine conflict"],[366,427,"ASEAN relations"],[428,490,"UN reform"],[491,552,"Brunei Darussalam economy"],[553,628,"Brunei Darussalam reconstruction"],[629,694,"UN reform"],[696,744,"International law"]],"stances":{"Ceremony":"Prince 'Abdul Mateen conveys greetings from the Sultan of Brunei and expresses congratulations and thanks to the newly elected President of the General Assembly, the previous session's leader, and the Secretary-General.","Trust erosion":"Prince 'Abdul Mateen argues that the loss of trust and faith in international rules is causing nations to act unilaterally, which weakens global stability.","Israel-Palestine conflict":"Prince 'Abdul Mateen asserts that the Palestinian people have waited too long for justice and statehood, and that the scale of suffering in Gaza is intolerable.","ASEAN relations":"Prince 'Abdul Mateen highlights the 50th anniversary of the Treaty of Amity and Cooperation in Southeast Asia as a practical example of applying principles like dialogue and restraint at the regional level.","UN reform":"Prince 'Abdul Mateen argues that UN reform must strengthen the organization's ability to prevent crises and deliver meaningful outcomes rather than merely rearranging structures.","Brunei Darussalam economy":"Prince 'Abdul Mateen states that Brunei's future preparation centers on its people through the three goals of Vision 2035, emphasizing that national strength depends on strong citizens rather than economic growth alone.","Brunei Darussalam reconstruction":"Prince 'Abdul Mateen argues that stability and development are interdependent requirements for a society where people can realize their full potential.","International law":"Prince 'Abdul Mateen argues that international law must apply equally regardless of power and that honoring existing promises is essential for restoring credibility."},"claims":[{"t":102,"quote":"Without it, treaties risk becoming little more than words. Institutions become arenas for accusation, and countries increasingly feel compelled to rely only","topic":"Trust erosion","kind":"fact"},{"t":125,"quote":"Today, we not only see declining confidence between countries, but a grow also a growing crisis of faith in the rules meant to bind us together.","topic":"Trust erosion","kind":"fact"},{"t":211,"quote":"For generations, the Palestinian people have waited for justice, statehood, and They cannot be asked to wait indefinitely for rights that are already In Gaza, the scale of human suffering and destruction is intolerable.","topic":"Israel-Palestine conflict","kind":"fact"},{"t":236,"quote":"Medics, journalists, humanitarian workers, and United Nations personnel have also lost their lives while carrying out their duties.","topic":"Israel-Palestine conflict","kind":"fact"},{"t":249,"quote":"In the West Bank, Palestinians continue to endure occupation, expanding illegal settlements, settle violence, and displacement from their homes and land.","topic":"Israel-Palestine conflict","kind":"fact"},{"t":327,"quote":"In neighboring Lebanon, United Nations peacekeepers have also lost their lives while serving the cause of peace.","topic":"Israel-Palestine conflict","kind":"fact"},{"t":337,"quote":"Bruno Salam co-sponsored security council resolution 2823 strengthening accountability for crimes against United Nations peacekeepers.","topic":"Israel-Palestine conflict","kind":"fact"},{"t":413,"quote":"This year marks the 50th anniversary of the Treaty of Amity and cooperation in Southeast Asia or the TAC.","topic":"ASEAN relations","kind":"fact"},{"t":422,"quote":"The TAC gives regional expression to the same fundamental principles found in the United Nations Charter.","topic":"ASEAN relations","kind":"fact"},{"t":444,"quote":"Azen's experience shows that institutions remain relevant when rules are respected, dialogue stays open, and differences are managed peacefully.","topic":"UN reform","kind":"fact"},{"t":527,"quote":"Built upon three mutually reinforcing goals. An educated, highly skilled and accomplished people, a high quality of life and a dynamic and sustainable economy.","topic":"Brunei Darussalam economy","kind":"fact"},{"t":549,"quote":"A country is strong when its people are strong.","topic":"Brunei Darussalam economy","kind":"fact"},{"t":553,"quote":"That means equipping our people with the knowledge and skills to adapt to change. It also means ensuring they have the security and stability to build their lives with confidence supported by strong communities, quality healthcare and essential services, social protection and a cohesive resilient For BrunA, stability and development go hand in hand.","topic":"Brunei Darussalam reconstruction","kind":"fact"},{"t":581,"quote":"Stability gives people the confidence to plan for tomorrow and development gives them the opportunity to build that Both must be sustained by a dynamic, diversified and resilient economy that creates meaningful opportunities and quality employment.","topic":"Brunei Darussalam reconstruction","kind":"fact"},{"t":629,"quote":"That is why no one left behind must be more than a phrase. It must be reflected in the choices we make and in the outcomes we deliver.","topic":"UN reform","kind":"fact"},{"t":648,"quote":"Confidence in the international system is strengthened when promises are kept. when international law is applied equally, when dialogue is chosen over force, when sovereignty is respected, and when every nation, large or small, knows that its voice matters.","topic":"UN reform","kind":"fact"},{"t":696,"quote":"Where dialogue remains preferable to where international law does not bend according to size or strength, and where justice is not determined by power.","topic":"International law","kind":"fact"},{"t":710,"quote":"The world does not need another pro promise that we failed to keep.","topic":"International law","kind":"fact"}],"promises":[{"t":733,"quote":"Brunam is ready to play its part.","topic":"International law","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":"Ceremony","text":"I now give the floor to his royal highness prince Abdul Matin, Minister of Foreign Affairs of Brunam. Rahim, Mr. President, Mr. Secretary General, excellencies, ladies and gentlemen. I wish to begin by conveying the warm greetings of his majesty sultan sultan and young deuan of salam to this esteemed assembly. I also congratulate his excellency Dr. Khalil Rahman on his election as president of the 81st session of the general assembly and thank her excellency Anelina Berbok for outstanding leadership during the 80th My appreciation also extends to Secretary General Antonio Gutierrez for his continued service to this Mr."},{"t":85,"topic":"Trust erosion","text":"President, the theme of the session speaks directly to something the world is losing far too quickly. Trust. It's difficult to build, easy to fracture, and once lost, very hard to Without it, treaties risk becoming little more than words. Institutions become arenas for accusation, and countries increasingly feel compelled to rely only on At a time of profound transformation, rebuilding confidence among nations lets us confront change and uncertainty Today, we not only see declining confidence between countries, but a grow also a growing crisis of faith in the rules meant to bind us together. When nations begin to believe that rules are applied differently depending on power or circumstance, the instinct is to turn inward and act alone. That weakens us all."},{"t":149,"topic":"Israel-Palestine conflict","text":"Dialogue becomes harder, multilateral institutions lose authority, and the international order becomes more fragile, leaving smaller and more vulnerable states particularly For Bernard Salam, multilateralism is not an intellectual concept. It is assurance that sovereignty and territorial integrity will be respected. That every nation, irrespective of size, has a voice, and that international law protects the weak as surely as it restrains the strong. The charter of the United Nations must therefore remain our common foundation. It cannot mean one thing in one crisis and something different in another. Its principles must be upheld consistently if this organization is to retain its legitimacy and credibility. Few issues demonstrate this more painfully than the question of For generations, the Palestinian people have waited for justice, statehood, and They cannot be asked to wait indefinitely for rights that are already In Gaza, the scale of human suffering and destruction is intolerable."},{"t":230,"topic":"Israel-Palestine conflict","text":"Civilians, including far too many children, continue to bear the heaviest Medics, journalists, humanitarian workers, and United Nations personnel have also lost their lives while carrying out their duties. This suffering cannot become normal. In the West Bank, Palestinians continue to endure occupation, expanding illegal settlements, settle violence, and displacement from their homes and land. Whether in Gaza or the West Bank, these are not merely numbers. They are human And their suffering exposes a fundamental truth. International law and the principles of the charter must apply equally to everyone. There cannot be one standard for some and another for others. A just and lasting peace therefore requires more than managing the consequences of conflict. It requires addressing its root cause and realizing the Palestinian people's legitimate right to self-determination and an independent state of Palestine based on the 1967 borders with East Jerusalem as its capital."},{"t":304,"topic":"Israel-Palestine conflict","text":"Without justice for the Palestinian people, there can be no lasting peace. This remains a defining test of the credibility of the United Nations and particularly the Security Council. And the conflict is no longer confined to Palestine. Its consequences are now spreading across the region. In neighboring Lebanon, United Nations peacekeepers have also lost their lives while serving the cause of peace. It is in this wider context that Bruno Salam co-sponsored security council resolution 2823 strengthening accountability for crimes against United Nations peacekeepers. Those who serve under the United Nations flag must be protected. But accountability cannot be episodic. The protection of those who serve peace and the protection of innocent lives, especially children, must remain at the heart of this organization. Mr."},{"t":366,"topic":"ASEAN relations","text":"President, rebuilding confidence does not mean returning to a world that no longer exists. It means equipping ourselves to face the world that is emerging. From conflicts and climate change to sustainable development and emerging technologies, the challenges before us are increasingly complex and interconnected. Transformation is already taking place. We must ensure it strengthens cooperation rather than deepens In Southeast Asia, Azen offers a practical example of how these principles can be applied at the regional level. Despite our differences, Azan has chosen dialogue, restraint, and continued This year marks the 50th anniversary of the Treaty of Amity and cooperation in Southeast Asia or the TAC. The TAC gives regional expression to the same fundamental principles found in the United Nations Charter."},{"t":428,"topic":"UN reform","text":"respect for sovereignty, peaceful sediments of disputes, non-inference, and cooperation among states. In this sense, the TAC does not stand apart from the multilateral system. It reinforces it. Azen's experience shows that institutions remain relevant when rules are respected, dialogue stays open, and differences are managed peacefully. The same must be true for the United Reform must not become an exercise in rearranging structures while confidence outside this hall continues to erode. Transformation must strengthen the United Nations ability to prevent crisis, respond effectively to member states, and deliver outcomes that make a meaningful difference to people's lives. Bernardam therefore supports initiatives such as the pact of the future and the UNAT initiative. Ultimately, reform must achieve more than efficiency."},{"t":491,"topic":"Brunei Darussalam economy","text":"It must strengthen this organization's credibility and its capacity to deliver. Mr. President, a United Nations that delivers for all must ultimately deliver for the people. That is the spirit of the 2030 agenda for sustainable development. At its heart is a simple promise that progress today should not come at the expense of tomorrow. For Brunam, preparing for the future begins with our people. This lies at the core of Brunai vision 2035. Built upon three mutually reinforcing goals. An educated, highly skilled and accomplished people, a high quality of life and a dynamic and sustainable economy. Together, these goals reflect our conviction that national progress cannot be measured by economic growth alone. A country is strong when its people are strong."},{"t":553,"topic":"Brunei Darussalam reconstruction","text":"That means equipping our people with the knowledge and skills to adapt to change. It also means ensuring they have the security and stability to build their lives with confidence supported by strong communities, quality healthcare and essential services, social protection and a cohesive resilient For BrunA, stability and development go hand in hand. Stability gives people the confidence to plan for tomorrow and development gives them the opportunity to build that Both must be sustained by a dynamic, diversified and resilient economy that creates meaningful opportunities and quality employment. Together they create the conditions in which people can realize their full potential. Our ambition is therefore not merely to build a more prosperous country, but a society in which people feel secure in the present, confident about the future, and equipped to shape that future for But progress loses its meaning when people feel less secure, less included, or less hopeful about what lies ahead."},{"t":629,"topic":"UN reform","text":"That is why no one left behind must be more than a phrase. It must be reflected in the choices we make and in the outcomes we deliver. Mr. President, the realities before us are complex, but the principles that should guide us remain clear. Confidence in the international system is strengthened when promises are kept. when international law is applied equally, when dialogue is chosen over force, when sovereignty is respected, and when every nation, large or small, knows that its voice matters. Therefore, to build the United Nations that delivers for all, we must always remember who all means, not institutions, not statistics. It is the people. The United Nations we build today will shape the world the next generation We owe them a world in which cooperation remains stronger than conflict."},{"t":696,"topic":"International law","text":"Where dialogue remains preferable to where international law does not bend according to size or strength, and where justice is not determined by power. The world does not need another pro promise that we failed to keep. It needs us to honor the promises we have already That is how credibility is restored. That is how multilateralism and international law remain relevant. And that is how we build a United Nations that truly delivers for all. Brunam is ready to play its part. Thank you. I thank the Minister of Foreign Affairs of Brun Jerusalem."}],"compare":[{"topic":"Israel–Palestine","share":0.3296,"mean":0.051,"rank":5,"others":76},{"topic":"UN & its reform","share":0.1952,"mean":0.2048,"rank":97,"others":170},{"topic":"International Law & Order","share":0.171,"mean":0.0598,"rank":22,"others":102},{"topic":"ASEAN","share":0.0948,"mean":0.0016,"rank":2,"others":4}]};
